-- Master templates are private snapshots. Tenant config remains fully independent.
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;

create table if not exists private.master_templates (
 id uuid primary key default gen_random_uuid(), template_key text not null unique, name text not null,
 version integer not null default 1, is_active boolean not null default true,
 is_ready boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists private.master_template_providers (
 id uuid primary key default gen_random_uuid(), template_id uuid not null references private.master_templates(id) on delete cascade,
 source_id uuid not null, provider_name text not null, provider_logo text, is_active boolean not null,
 display_order integer not null default 0, evoucher_rate numeric not null default 0, promotional_text text,
 unique(template_id,source_id)
);
create table if not exists private.master_template_categories (
 id uuid primary key default gen_random_uuid(), template_id uuid not null references private.master_templates(id) on delete cascade,
 source_id uuid not null, source_provider_id uuid not null, category_name text not null, display_order integer not null default 0,
 is_active boolean not null, category_image text, unique(template_id,source_id)
);
create table if not exists private.master_template_packages (
 id uuid primary key default gen_random_uuid(), template_id uuid not null references private.master_templates(id) on delete cascade,
 source_id uuid not null, source_provider_id uuid not null, source_category_id uuid,
 package_name text not null, data_amount text not null, validity_days text not null, cost_price numeric not null,
 selling_price numeric not null, profit_margin numeric, is_active boolean not null, connection_type_label text not null,
 ussd_code text, display_order integer not null default 0, is_discovery_root boolean not null default false,
 is_ussd_only boolean not null default false, unique(template_id,source_id)
);
create table if not exists private.master_template_delivery (
 id uuid primary key default gen_random_uuid(), template_id uuid not null references private.master_templates(id) on delete cascade,
 source_id uuid not null, source_provider_id uuid, source_category_id uuid, source_package_id uuid,
 instruction_type text not null default 'ussd', ussd_code text, provider_name text, execution_order integer default 1,
 code_template text, sim_password text, notes text, instruction_template text default '', unique(template_id,source_id)
);
create table if not exists private.tenant_template_entities (
 tenant_id uuid not null references public.tenants(id) on delete cascade,
 template_id uuid not null references private.master_templates(id) on delete cascade,
 entity_type text not null check(entity_type in ('provider','category','package','delivery')),
 source_id uuid not null, target_id uuid not null, created_at timestamptz not null default now(),
 primary key(tenant_id,template_id,entity_type,source_id)
);
create table if not exists private.tenant_template_applications (
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade,
 template_id uuid not null references private.master_templates(id), template_version integer not null,
 result jsonb not null default '{}'::jsonb, applied_at timestamptz not null default now()
);
alter table private.master_templates enable row level security;
alter table private.master_template_providers enable row level security;
alter table private.master_template_categories enable row level security;
alter table private.master_template_packages enable row level security;
alter table private.master_template_delivery enable row level security;
alter table private.tenant_template_entities enable row level security;
alter table private.tenant_template_applications enable row level security;

values ('xog-dhameystiran-iftin','Xog Dhameystiran – Iftin Internet',1,true,false)
on conflict(template_key) do nothing;

create or replace function public.apply_master_template_to_tenant(p_tenant_id uuid,p_template_key text)
returns jsonb language plpgsql security definer set search_path='pg_catalog','public','private' as $$
declare
 v_template private.master_templates%rowtype; r record; v_target uuid; v_provider uuid; v_category uuid; v_package uuid;
 n_providers int:=0; n_categories int:=0; n_packages int:=0; n_delivery int:=0; n_reused int:=0; v_result jsonb;
begin
 select * into v_template from private.master_templates where template_key=p_template_key and is_active=true;
 if not found then raise exception 'template_not_found'; end if;
 if not v_template.is_ready then raise exception 'template_not_ready'; end if;
 if not exists(select 1 from public.tenants where id=p_tenant_id) then raise exception 'tenant_not_found'; end if;

 for r in select * from private.master_template_providers where template_id=v_template.id order by display_order,id loop
  select target_id into v_target from private.tenant_template_entities where tenant_id=p_tenant_id and template_id=v_template.id and entity_type='provider' and source_id=r.source_id;
  if v_target is null then
   select id into v_target from public.providers_config where tenant_id=p_tenant_id and lower(btrim(provider_name))=lower(btrim(r.provider_name)) limit 1;
   if v_target is null then
    values(p_tenant_id,r.provider_name,r.provider_logo,r.is_active,r.display_order,r.evoucher_rate,r.promotional_text) returning id into v_target;
    n_providers:=n_providers+1;
   else n_reused:=n_reused+1; end if;
  else n_reused:=n_reused+1; end if;
 end loop;

 for r in select * from private.master_template_categories where template_id=v_template.id order by display_order,id loop
  select target_id into v_provider from private.tenant_template_entities where tenant_id=p_tenant_id and template_id=v_template.id and entity_type='provider' and source_id=r.source_provider_id;
  if v_provider is null then raise exception 'provider_mapping_missing:%',r.source_provider_id; end if;
  select target_id into v_target from private.tenant_template_entities where tenant_id=p_tenant_id and template_id=v_template.id and entity_type='category' and source_id=r.source_id;
  if v_target is null then
   select id into v_target from public.package_categories where tenant_id=p_tenant_id and provider_id=v_provider and lower(btrim(category_name))=lower(btrim(r.category_name)) limit 1;
   if v_target is null then
    values(p_tenant_id,v_provider,r.category_name,r.display_order,r.is_active,r.category_image) returning id into v_target;
    n_categories:=n_categories+1;
   else n_reused:=n_reused+1; end if;
  else n_reused:=n_reused+1; end if;
 end loop;

 for r in select * from private.master_template_packages where template_id=v_template.id order by display_order,id loop
  select target_id into v_provider from private.tenant_template_entities where tenant_id=p_tenant_id and template_id=v_template.id and entity_type='provider' and source_id=r.source_provider_id;
  v_category:=null;
  if r.source_category_id is not null then select target_id into v_category from private.tenant_template_entities where tenant_id=p_tenant_id and template_id=v_template.id and entity_type='category' and source_id=r.source_category_id; end if;
  if v_provider is null then raise exception 'provider_mapping_missing:%',r.source_provider_id; end if;
  select target_id into v_target from private.tenant_template_entities where tenant_id=p_tenant_id and template_id=v_template.id and entity_type='package' and source_id=r.source_id;
  if v_target is null then
   select id into v_target from public.data_packages_config where tenant_id=p_tenant_id and provider_id=v_provider and category_id is not distinct from v_category and package_name=r.package_name and data_amount=r.data_amount and validity_days=r.validity_days and cost_price=r.cost_price and selling_price=r.selling_price limit 1;
   if v_target is null then
    values(p_tenant_id,v_provider,v_category,r.package_name,r.data_amount,r.validity_days,r.cost_price,r.selling_price,r.profit_margin,r.is_active,r.connection_type_label,r.ussd_code,r.display_order,r.is_discovery_root,r.is_ussd_only) returning id into v_target;
    n_packages:=n_packages+1;
   else n_reused:=n_reused+1; end if;
  else n_reused:=n_reused+1; end if;
 end loop;

 for r in select * from private.master_template_delivery where template_id=v_template.id order by execution_order,id loop
  v_provider:=null;v_category:=null;v_package:=null;
  if r.source_provider_id is not null then select target_id into v_provider from private.tenant_template_entities where tenant_id=p_tenant_id and template_id=v_template.id and entity_type='provider' and source_id=r.source_provider_id; end if;
  if r.source_category_id is not null then select target_id into v_category from private.tenant_template_entities where tenant_id=p_tenant_id and template_id=v_template.id and entity_type='category' and source_id=r.source_category_id; end if;
  if r.source_package_id is not null then select target_id into v_package from private.tenant_template_entities where tenant_id=p_tenant_id and template_id=v_template.id and entity_type='package' and source_id=r.source_package_id; end if;
  select target_id into v_target from private.tenant_template_entities where tenant_id=p_tenant_id and template_id=v_template.id and entity_type='delivery' and source_id=r.source_id;
  if v_target is null then
   select id into v_target from public.delivery_instructions where tenant_id=p_tenant_id and provider_id is not distinct from v_provider and category_id is not distinct from v_category and package_id is not distinct from v_package and code_template is not distinct from r.code_template limit 1;
   if v_target is null then
    values(p_tenant_id,r.instruction_type,r.ussd_code,r.provider_name,r.execution_order,v_provider,v_category,v_package,r.code_template,r.sim_password,r.notes,r.instruction_template) returning id into v_target;
    n_delivery:=n_delivery+1;
   else n_reused:=n_reused+1; end if;
  else n_reused:=n_reused+1; end if;
 end loop;
 v_result:=jsonb_build_object('template_key',v_template.template_key,'version',v_template.version,'inserted',jsonb_build_object('providers',n_providers,'categories',n_categories,'packages',n_packages,'delivery_instructions',n_delivery),'reused',n_reused);
 return v_result;
end $$;
revoke all on function public.apply_master_template_to_tenant(uuid,text) from public,anon,authenticated;
grant execute on function public.apply_master_template_to_tenant(uuid,text) to service_role;
